    input = sys.stdin.readline
    N, M = map(int, input().split())
    parent = list(range(N + 1))
    rank = [0] * (N + 1)

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return False
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        if rank[ra] == rank[rb]:
            rank[ra] += 1
        return True

    kept = 0
    for _ in range(M):
        u, v = map(int, input().split())
        if union(u, v):
            kept += 1
    print(M - kept)

