class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        sets = [set(row) for row in properties]

        parent = list(range(n))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb

        for i in range(n):
            for j in range(i + 1, n):
                if len(sets[i] & sets[j]) >= k:
                    union(i, j)

        return len({find(i) for i in range(n)})

class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        a = [ord(c) - 97 for c in s]

        # cyclic distance on alphabet of size 26
        D = [[0] * 26 for _ in range(26)]
        for i in range(26):
            for j in range(26):
                d = abs(i - j)
                if d > 13:
                    d = 26 - d
                D[i][j] = d

        # dp[l][r] = list of length k+1; dp[l][r][u] = longest palindromic
        # subsequence obtainable inside s[l..r] using at most u operations.
        dp = [[None] * n for _ in range(n)]
        for l in range(n):
            dp[l][l] = [1] * (k + 1)

        for length in range(2, n + 1):
            for l in range(0, n - length + 1):
                r = l + length - 1
                x = a[l]
                y = a[r]

                costs = [D[x][t] + D[y][t] for t in range(26)]
                min_all = min(costs)

                # min_le[u] = min cost_t with cost_t <= u  (only needed for u <= 26)
                cap = min(k, 26)
                min_le = [None] * (cap + 1)
                for c in costs:
                    if c > cap:
                        continue
                    for u in range(c, cap + 1):
                        if min_le[u] is None or c < min_le[u]:
                            min_le[u] = c

                inner = dp[l + 1][r - 1] if l + 1 <= r - 1 else None
                skip_l = dp[l + 1][r]
                skip_r = dp[l][r - 1]

                row = [0] * (k + 1)
                prev = None
                for u in range(k + 1):
                    best = skip_l[u]
                    v = skip_r[u]
                    if v > best:
                        best = v

                    mm = min_le[u] if u <= cap else min_all
                    if mm is not None:
                        idx = u - mm
                        if inner is None:
                            cand = 2
                        else:
                            cand = 2 + inner[idx]
                        if cand > best:
                            best = cand

                    if prev is not None and prev > best:
                        best = prev
                    row[u] = best
                    prev = best

                dp[l][r] = row

        return dp[0][n - 1][k]

