class Solution:
    def minTime(self, skill: List[int], mana: List[int]) -> int:
        n = len(skill)
        m = len(mana)

        prefix = [0] * n
        s = 0
        for i in range(n):
            s += skill[i]
            prefix[i] = s

        free = [0] * n

        for j in range(m):
            mj = mana[j]
            x = free[0]
            for i in range(1, n):
                cand = free[i] - prefix[i - 1] * mj
                if cand > x:
                    x = cand
            for i in range(n):
                free[i] = x + prefix[i] * mj

        return free[n - 1]

