class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        # DP over (parity, sum) -> set of achievable products (<= limit)
        # plus track whether a "too big" product (> limit) is achievable,
        # since a later 0 can reset the product to 0.
        #
        # We keep for each (parity, sum):
        #   - the maximum product <= limit reachable
        #   - a flag whether some reachable product is > limit
        #
        # Actually we need the full set of products <= limit? No:
        # the counterexample shows keeping only the max <= limit can lose
        # the answer. We therefore keep the set of achievable products
        # (<= limit) per (parity, sum). This is bounded by limit+1 values.

        empty = {(0, 0): {1}}          # parity 0, sum 0, product 1 (empty)
        nonempty = {}                   # (parity, sum) -> set of products

        for x in nums:
            new_nonempty = {}
            # persist nonempty states (not taking x)
            for key, prods in nonempty.items():
                new_nonempty[key] = set(prods)
            # take x from nonempty
            for (p, s), prods in nonempty.items():
                np_ = 1 - p
                ns = s + (x if p == 0 else -x)
                for prod in prods:
                    nprod = prod * x
                    if nprod <= limit:
                        new_nonempty.setdefault((np_, ns), set()).add(nprod)
                    else:
                        # product > limit: keep a marker so we can later
                        # reset to 0 via a zero element
                        new_nonempty.setdefault((np_, ns), set()).add(limit + 1)
            # take x from empty
            for (p, s), prods in empty.items():
                # p == 0, s == 0, prod == 1
                np_ = 1
                ns = s + x
                for prod in prods:
                    nprod = prod * x
                    if nprod <= limit:
                        new_nonempty.setdefault((np_, ns), set()).add(nprod)
                    else:
                        new_nonempty.setdefault((np_, ns), set()).add(limit + 1)
            nonempty = new_nonempty
            # empty persists unchanged

        ans = -1
        for (p, s), prods in nonempty.items():
            if s == k:
                for prod in prods:
                    if prod <= limit and prod > ans:
                        ans = prod
        return ans

