class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        def perimeter_t(p):
            x, y = p
            if y == 0:
                return x                      # bottom side
            if x == side:
                return side + y               # right side
            if y == side:
                return 3 * side - x           # top side
            return 4 * side - y               # left side

        pts = sorted(points, key=perimeter_t)

        def feasible(d: int) -> bool:
            selected = []
            for x, y in pts:
                ok = True
                for sx, sy in selected:
                    if abs(x - sx) + abs(y - sy) < d:
                        ok = False
                        break
                if ok:
                    selected.append((x, y))
                    if len(selected) >= k:
                        return True
            return len(selected) >= k

        lo, hi = 0, 2 * side
        while hi - lo > 1:
            mid = (lo + hi) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid
        return lo

