class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        total = 0
        for i in range(n):
            mn = nums[i]
            mx = nums[i]
            end = min(i + k, n)  # j ranges over [i, min(i+k-1, n-1)]
            for j in range(i, end):
                v = nums[j]
                if v < mn:
                    mn = v
                if v > mx:
                    mx = v
                total += mn + mx
        return total

