class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        children = [{}]          # node -> {char: next_node}
        depth = [0]
        cnt = [0]

        for w in words:
            node = 0
            for ch in w:
                nxt = children[node].get(ch)
                if nxt is None:
                    nxt = len(children)
                    children[node][ch] = nxt
                    children.append({})
                    depth.append(depth[node] + 1)
                    cnt.append(0)
                node = nxt
                cnt[node] += 1

        m = len(children)

        # iterative preorder, then reverse for postorder
        order = []
        stack = [0]
        while stack:
            x = stack.pop()
            order.append(x)
            for nxt in children[x].values():
                stack.append(nxt)

        best = [-1] * m
        top1 = [-1] * m
        top2 = [-1] * m

        for x in reversed(order):
            m1 = -1
            m2 = -1
            for nxt in children[x].values():
                b = best[nxt]
                if b > m1:
                    m2 = m1
                    m1 = b
                elif b > m2:
                    m2 = b
            top1[x] = m1
            top2[x] = m2
            cand = depth[x] if cnt[x] >= k else -1
            best[x] = cand if cand > m1 else m1

        ans = [0] * n
        for i, w in enumerate(words):
            path = [0]
            node = 0
            for ch in w:
                node = children[node][ch]
                path.append(node)

            cur = 0
            need_cnt = k + 1
            for pos, x in enumerate(path):
                if cnt[x] >= need_cnt:
                    d = depth[x]
                    if d > cur:
                        cur = d

                m1 = top1[x]
                if m1 != -1:
                    nxt = path[pos + 1] if pos + 1 < len(path) else None
                    if nxt is None:
                        sib = m1
                    else:
                        sib = top2[x] if best[nxt] == m1 else m1
                    if sib > cur:
                        cur = sib

            ans[i] = cur

        return ans
